<?php require __DIR__.'/inc/core.php';auth();$pdo=db();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Geçersiz müşteri.');}$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$c=$s->fetch();if(!$c){http_response_code(404);exit('Müşteri bulunamadı.');}$s=$pdo->prepare('SELECT id,quote_no,origin,destination,volume,total,currency,status,created_at FROM quotes WHERE customer_id=? ORDER BY id DESC LIMIT 100');$s->execute([$id]);$qs=$s->fetchAll();$contracts=[];$contractError='';
try{$s=$pdo->prepare('SELECT vc.id,vc.quote_id,vc.language,q.quote_no,q.origin,q.destination FROM v11_contracts vc JOIN quotes q ON q.id=vc.quote_id WHERE q.customer_id=? ORDER BY vc.id DESC');$s->execute([$id]);$contracts=$s->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$contractError='Sözleşmeler görüntülenemiyor.';}
$contractByQuote=[];foreach($contracts as $ct){$contractByQuote[(int)$ct['quote_id']]=$ct;}
require __DIR__.'/inc/layout.php';top('Müşteri Profili');?>
