im</th><th>Toplam</th><th>Durum</th><th>Sözleşme</th><th>İşlem</th></tr></thead><tbody><?php foreach($qs as $q):?><tr><td><?=h($q['quote_no'])?></td><td><?=h($q['origin'])?> → <?=h($q['destination'])?></td><td><?=number_format((float)$q['volume'],2,',','.')?> m³</td><td><?=money($q['total'],$q['currency'])?></td><td><?=h(statusText($q['status']))?></td><td><?php if(isset($contractByQuote[(int)$q['id']])): ?><a href="v11-documents.php?id=<?=(int)$q['id']?>">Düzenle</a> · <a target="_blank" rel="noopener" href="v11-print.php?id=<?=(int)$q['id']?>&amp;type=contract">PDF</a><?php else: ?><a href="v11-documents.php?id=<?=(int)$q['id']?>">Sözleşme Oluştur</a><?php endif;?></td><td><a href="view.php?id=<?=(int)$q['id']?>">Aç</a> · <a href="quote-actions.php?id=<?=(int)$q['id']?>">İşlemler</a></td></tr><?php endforeach;?><?php if(!$qs):?><tr><td colspan="7">Bu müşteri için henüz teklif yok.</td></tr><?php endif;?></tbody></table></div><h2 id="sozlesmeler" style="margin-top:28px;scroll-margin-top:20px">Sözleşme Geçmişi</h2><?php if($contractError):?><p class="hub-info"><?=h($contractError)?></p><?php endif;?><div style="overflow:auto"><table class="hub-table"><thead><tr><th>Teklif</th><th>Güzergâh</th><th>Dil</th><th>İşlemler</th></tr></thead><tbody><?php foreach($contracts as $ct):?><tr><td><?=h($ct['quote_no'])?></td><td><?=h($ct['origin'])?> → <?=h($ct['destination'])?></td><td><?=h(strtoupper($ct['language']))?></td><td><a href="v11-documents.php?id=<?=(int)$ct['quote_id']?>">Yönet</a> · <a target="_blank" rel="noopener" href="v11-print.php?id=<?=(int)$ct['quote_id']?>&amp;type=contract">PDF</a></td></tr><?php endforeach;?><?php if(!$contracts):?><tr><td colspan="4">Bu müşterinin henüz sözleşmesi yok.</td></tr><?php endif;?></tbody></table></div><?php bottom();?>